begin;
set local search_path=public,extensions;
select plan(24);
grant usage on schema extensions to authenticated;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('f2420000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','central-fiscal242-'||i||'@example.invalid',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)values('f2420000-0000-4000-8000-000000000001','FINANCE_MANAGER'),('f2420000-0000-4000-8000-000000000002','SUPER_ADMIN'),('f2420000-0000-4000-8000-000000000003','MATRICIA_ADMIN');
insert into public.tax_categories(code,name_fr,name_ar,description_fr,description_ar,category_kind,status)values('TEST_CENTRAL242','TEST fiscal central','ضريبة اختبار مركزية','Synthetic tax category for rollback','فئة اختبار مؤقت','SERVICE','ACTIVE');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('f2421000-0000-4000-8000-000000000001','TEST tenant242','TEST tenant242','ACTIVE','f2420000-0000-4000-8000-000000000001');
create temporary table results(k text primary key,v jsonb);grant all on results to authenticated;
select is((select count(*)from public.organization_memberships where user_id::text like'f2420000-%'),0::bigint,'central reviewers have no organization membership');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f2420000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.get_morocco_tax_context_v1()$$,'42501','MOROCCO_TAX_ADMIN_AAL2_REQUIRED','ordinary actor has no platform fiscal context');
select set_config('request.jwt.claims','{"sub":"f2420000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.list_morocco_tax_rules()$$,'42501','MOROCCO_TAX_ADMIN_AAL2_REQUIRED','administration role alone cannot read central fiscal governance');
select set_config('request.jwt.claims','{"sub":"f2420000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.get_morocco_tax_context_v1()$$,'42501','MOROCCO_TAX_ADMIN_AAL2_REQUIRED','finance context requires AAL2');
select set_config('request.jwt.claims','{"sub":"f2420000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is(public.get_morocco_tax_context_v1(),'{"kind":"PLATFORM"}'::jsonb,'finance without membership receives explicit PLATFORM context');
select ok(jsonb_typeof(public.list_morocco_tax_rules()->'rules')='array','central reviewer reads the real global rule catalogue');
select throws_ok($$select public.propose_morocco_tax_rule('f2421000-0000-4000-8000-000000000001','TEST_CENTRAL242','VAT',2000,10,'{}','TEST synthetic fiscal source, not legal approval',current_date,null,'TEST platform fiscal proposal','central-tax242-key')$$,'42501','MOROCCO_TAX_PROPOSAL_DENIED','central scope never grants membership in a supplied tenant');
insert into results values('proposal',public.propose_morocco_tax_rule(null,'TEST_CENTRAL242','VAT',2000,10,'{}','TEST synthetic fiscal source, not legal approval',current_date,null,'TEST platform fiscal proposal','central-tax242-key'));
select is((select v->>'outcome'from results where k='proposal'),'MOROCCO_TAX_RULE_PROPOSED','central command creates a real draft without an organization UUID');
select is(public.propose_morocco_tax_rule(null,'TEST_CENTRAL242','VAT',2000,10,'{}','TEST synthetic fiscal source, not legal approval',current_date,null,'TEST platform fiscal proposal','central-tax242-key'),(select v from results where k='proposal'),'central proposal lost reply replays exactly');
select throws_ok($$select public.propose_morocco_tax_rule(null,'TEST_CENTRAL242','VAT',2100,10,'{}','TEST synthetic fiscal source, not legal approval',current_date,null,'TEST platform fiscal proposal','central-tax242-key')$$,'22000','IDEMPOTENCY_PAYLOAD_MISMATCH','central key cannot replay a changed monetary rate');
select throws_ok($$select public.decide_morocco_tax_rule(null,(select(v->>'tax_rule_version_id')::uuid from results where k='proposal'),'APPROVE','VALIDATED','TEST/242/VALIDATION','TEST independent fiscal validation',1,'central-tax242-review')$$,'42501','MOROCCO_TAX_DECISION_DENIED','author cannot approve their own platform tax rule');
select set_config('request.jwt.claims','{"sub":"f2420000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.decide_morocco_tax_rule(null,(select(v->>'tax_rule_version_id')::uuid from results where k='proposal'),'APPROVE','VALIDATED','TEST/242/VALIDATION','TEST independent fiscal validation',null,'central-tax242-review-null')$$,'40001','STALE_MOROCCO_TAX_RULE','NULL expected version cannot bypass governance CAS');
insert into results values('approved',public.decide_morocco_tax_rule(null,(select(v->>'tax_rule_version_id')::uuid from results where k='proposal'),'APPROVE','VALIDATED','TEST/242/VALIDATION','TEST independent fiscal validation',1,'central-tax242-review'));
select is((select v->>'outcome'from results where k='approved'),'MOROCCO_TAX_RULE_ACTIVATED','distinct central reviewer activates the real validated rule');
select is(public.decide_morocco_tax_rule(null,(select(v->>'tax_rule_version_id')::uuid from results where k='proposal'),'APPROVE','VALIDATED','TEST/242/VALIDATION','TEST independent fiscal validation',1,'central-tax242-review'),(select v from results where k='approved'),'central decision replays before mutable lifecycle checks');
select is((public.simulate_morocco_tax('TEST_CENTRAL242',current_date,10001)->>'tax_amount_minor'),'2000','approved central configuration drives the existing exact tax engine');
reset role;
select is((select count(*)from public.audit_events where organization_id is null and resource_id=(select v->>'tax_rule_version_id'from results where k='proposal')and action in('morocco.tax_rule.proposed','morocco.tax_rule.decided')),2::bigint,'central governance appends audit with NULL organization');
select is((select count(*)from public.event_outbox where organization_id is null and aggregate_id=(select v->>'tax_rule_version_id'from results where k='proposal')and event_type in('MoroccoTaxRuleProposedV1','MoroccoTaxRuleActivatedV1')),2::bigint,'central rule emits real platform outbox facts without a fake tenant');
select is((select count(*)from private.platform_tax_command_keys where actor_user_id::text like'f2420000-%'and status='COMPLETED'),2::bigint,'exactly two platform command keys persist after failed and replayed attempts');
select is((select count(*)from public.idempotency_keys where created_by::text like'f2420000-%'),0::bigint,'central commands never fabricate tenant command rows');
insert into public.organization_memberships(id,organization_id,user_id,status)values('f2422000-0000-4000-8000-000000000001','f2421000-0000-4000-8000-000000000001','f2420000-0000-4000-8000-000000000001','ACTIVE');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"f2420000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is((public.propose_morocco_tax_rule('f2421000-0000-4000-8000-000000000001','TEST_CENTRAL242','VAT',2000,10,'{}','TEST synthetic fiscal source, not legal approval',current_date,null,'TEST platform fiscal proposal','central-tax242-key')->>'outcome'),'MOROCCO_TAX_RULE_PROPOSED','explicit authorized organization context preserves the legacy command path');
reset role;
select is((select count(*)from public.idempotency_keys where organization_id='f2421000-0000-4000-8000-000000000001'),1::bigint,'organization command retains its separate real tenant key');
select ok(not has_table_privilege('authenticated','private.platform_tax_command_keys','INSERT'),'browser cannot fabricate completed platform commands');
select throws_ok($$update private.platform_tax_command_keys set request_hash=repeat('f',64)where actor_user_id='f2420000-0000-4000-8000-000000000001'$$,'55000','PLATFORM_TAX_COMMAND_IMMUTABLE','completed platform command history is immutable');
select is((select count(*)from public.organization_memberships where user_id='f2420000-0000-4000-8000-000000000002'),0::bigint,'independent reviewer remains entirely outside tenant membership');
select *from finish();
rollback;
